    async def start_bmc_access(
        self,
        *,
        server_id: str,
        ip: str,
        zone: str | None = None,
    ) -> BMCAccess:
        """
        Start BMC access

        Start BMC (Baseboard Management Controller) access associated with the ID.
        The BMC (Baseboard Management Controller) access is available one hour after the
        installation of the server.
        You need first to create an option Remote Access. You will find the ID and the
        price with a call to listOffers
        (https://developers.scaleway.com/en/products/baremetal/api/#get-78db92). Then
        add the option
        https://developers.scaleway.com/en/products/baremetal/api/#post-b14abd.
        After adding the BMC option, you need to Get Remote Access to get the
        login/password https://developers.scaleway.com/en/products/baremetal/api/#get-
        cefc0f. Do not forget to delete the Option after use.

        Args:
            zone: The zone you want to target
            server_id: ID of the server.
            ip: The IP authorized to connect to the server. (IPv4 address)
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/baremetal/v1/zones/{zone}/servers/{server_id}/bmc-access",
                zone=self._client.zone(zone),
                server_id=server_id,
            ),
            body={"ip": ip},
        )
        return BMCAccess.model_validate(data)

