    async def install_server(
        self,
        *,
        server_id: str,
        os_id: str,
        hostname: str,
        ssh_key_ids: list[str],
        zone: str | None = None,
        user: str | None = None,
        password: str | None = None,
        service_user: str | None = None,
        service_password: str | None = None,
        partitioning_schema: Schema | None = None,
        user_data: File | None = None,
        network_boot_url: str | None = None,
        network_boot_persistent: bool | None = None,
    ) -> Server:
        """
        Install an Elastic Metal server

        Install an Operating System (OS) on the Elastic Metal server with a specific ID.

        Args:
            zone: The zone you want to target
            server_id: Server ID to install.
            os_id: ID of the OS to installation on the server.
            hostname: Hostname of the server.
            ssh_key_ids: SSH key IDs authorized on the server.
            user: User used for the installation.
            password: Password used for the installation.
            service_user: User used for the service to install.
            service_password: Password used for the service to install.
            partitioning_schema: Partitioning schema.
            user_data: Configuration data to pass to cloud-init such as a YAML cloud
                config data or a user-data script.
            network_boot_url: URL of the network service to which the server should
                forward its boot request.
            network_boot_persistent: Defines whether the network boot forwarding should
                be applied at every reboot or only once.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/baremetal/v1/zones/{zone}/servers/{server_id}/install",
                zone=self._client.zone(zone),
                server_id=server_id,
            ),
            body={
                "os_id": os_id,
                "hostname": hostname,
                "ssh_key_ids": ssh_key_ids,
                "user": user,
                "password": password,
                "service_user": service_user,
                "service_password": service_password,
                "partitioning_schema": partitioning_schema,
                "user_data": user_data,
                "network_boot_url": network_boot_url,
                "network_boot_persistent": network_boot_persistent,
            },
        )
        return Server.model_validate(data)

